-- Content pack 3: ARTICLES (a / an / the / no article). 8 rules, 48 examples, 80 exercises.
-- GENERATED by scripts/build-articles-pack.mjs from database/rules-import/articles-pack.json. Do not edit by hand;
-- edit the JSON and run the script again.
--
-- What it does: adds the article rules to the Rules page (category english_grammar, shown as "English grammar"),
-- each with a short explanation, examples and multiple-choice exercises. Ids are fixed, so the offline copy
-- in the app (src/data/builtInRules.json) matches the database rows exactly.
-- Safe to run more than once: rules are unique on slug, examples and exercises are guarded against duplicates.
-- Run it in the Supabase SQL Editor (project "SpellSprint"). Needs rules-schema.sql to be applied already.
--
-- HOW TO UNDO (removes the rules; their examples and exercises go with them, learner progress on them too):
--   delete from public.rules where slug in ('a-or-an', 'a-or-the', 'the-one-of-a-kind', 'no-article-in-general', 'no-article-names-meals-languages', 'the-geography', 'no-article-routine-places', 'a-with-jobs-and-quantities');

begin;

insert into public.rules (id, slug, title, category, rule_type, short_explanation, tts_text, mnemonic, source, visibility, is_active)
values
  ('33b5bb10-2e28-53b8-ad5e-421088a82453', 'a-or-an', 'A or an: the sound decides', 'english_grammar', 'language_rule', 'Use a before a consonant SOUND and an before a vowel SOUND. Listen to the first sound of the next word, not its first letter: an hour (the h is silent), a university (it starts with the sound "yoo").', 'Use a before a consonant sound and an before a vowel sound.', 'Say the next word aloud. Does it start with a vowel sound? Then an.', 'built-in', 'public', true),
  ('d284d7c3-a1c6-54f9-a509-e0b0b095d54a', 'a-or-the', 'A or the: new or already known?', 'english_grammar', 'language_rule', 'Use a / an when you mention something for the first time or mean any one of its kind. Use the when the listener already knows which one: it was mentioned before, it is clear from the situation, or there is only one.', 'Use a for something new, and the for something already known.', 'A: any one, new. The: that one, we both know it.', 'built-in', 'public', true),
  ('52f0d52a-a054-549c-9322-e8dddc5fc8af', 'the-one-of-a-kind', 'The with one-of-a-kind things, superlatives and ordinals', 'english_grammar', 'language_rule', 'Use the when there is only one: the sun, the moon, the Internet. Use the with superlatives (the best, the most beautiful), with ordinals (the first, the second) and with the only / the same / the next / the last.', 'Use the with things that are unique, superlatives and ordinal numbers.', 'Only one? The. Best, first, last, only? The.', 'built-in', 'public', true),
  ('07d93c96-9aab-5b07-94ef-eca1d223d89c', 'no-article-in-general', 'No article for things in general', 'english_grammar', 'language_rule', 'When you talk about a whole group or an idea in general, use no article with plural and uncountable nouns: I love music. Cats are independent. Life is not easy. Use the only when you mean something specific: The music at the party was too loud.', 'Use no article for plural and uncountable nouns when you mean them in general.', 'In general: nothing. Specific: the.', 'built-in', 'public', true),
  ('b9895f4b-2982-5d7a-b1b0-9612c15756f4', 'no-article-names-meals-languages', 'No article: names, meals, languages, sports', 'english_grammar', 'language_rule', 'Use no article with names of people, most cities and countries, languages, sports and the meals: Paris, Canada, French, football, breakfast. If you add an adjective to a meal, you need a: We had a wonderful lunch.', 'No article with names, languages, sports and meals.', 'Names, languages, games and meals walk alone.', 'built-in', 'public', true),
  ('7d7a320f-a7d0-5df4-9ad0-cc11d2752524', 'the-geography', 'The with rivers, seas, mountain ranges and plural countries', 'english_grammar', 'language_rule', 'Use the with oceans, seas, rivers and mountain ranges (the Atlantic, the Thames, the Alps), with plural names (the Netherlands, the United States) and with countries that have words like Kingdom, Republic or States in the name. Most single countries, cities, lakes and single mountains take no article: Japan, Lake Geneva, Mount Everest.', 'Use the with oceans, rivers, mountain ranges and plural country names.', 'Water and groups take the. Single places walk alone.', 'built-in', 'public', true),
  ('844da00f-5777-576f-ad36-9a7a1dd4dd59', 'no-article-routine-places', 'Routine places and transport: go to school, by bus', 'english_grammar', 'language_rule', 'Some places and times are used for their normal purpose and take no article: go to school (as a pupil), go to work, be at home, go to bed, at night, by bus, by train. If you mean the building or one particular thing, use the: I am going to the school to speak to the teacher.', 'No article with routine places and with by plus transport.', 'Normal use: no article. A particular building: the.', 'built-in', 'public', true),
  ('fe8cd0fc-3329-5f6c-b932-353212cc3d00', 'a-with-jobs-and-quantities', 'A / an with jobs, per, and quantity words', 'english_grammar', 'language_rule', 'Use a / an with a job when you say what someone is: She is a teacher. Use a / an to mean per: twice a week, ten pounds an hour. Quantity expressions also take a: a few, a little, a lot of, half an hour, such a, what a. Few and little without a mean "not enough".', 'Use a or an with jobs, with per, and in a few, a little, such a, what a.', 'A job, a week, a few, a little: the little word a is needed.', 'built-in', 'public', true)
on conflict (slug) do nothing;

insert into public.rule_examples (id, rule_id, example_type, text, correction, note)
