  ('8fc6af53-bb79-5ccc-8654-594c064a8ae7', 'a-or-the', 'correct', 'I bought a dress and a bag. The dress was expensive.', null, 'first a, then the: it was already mentioned'),
  ('31b4dba1-a4ab-52d5-ad96-c3149014b614', 'a-or-the', 'correct', 'Can you close the window? It is cold.', null, 'both people know which window'),
  ('61c6341e-7de9-5026-882e-909f1896ff4a', 'a-or-the', 'correct', 'We need a new teacher.', null, 'any teacher, not a particular one'),
  ('b53469ce-624f-58d4-beed-3c02646a4ed6', 'a-or-the', 'incorrect', 'I have a car. A car is old but reliable.', 'I have a car. The car is old but reliable.', 'the same car, so the'),
  ('caa7f1ad-30d7-5cc2-b601-c3554b33bf97', 'a-or-the', 'incorrect', 'Pass me a salt, please.', 'Pass me the salt, please.', 'the salt on the table, and salt has no a'),
  ('fffb6348-8b9b-5b5d-bd95-d33e0269c210', 'a-or-the', 'exception', 'She wore the same dress.', null, 'the same, the next, the other always take the'),
  ('4f6f408b-9d9f-552d-b2b1-703b948828b0', 'the-one-of-a-kind', 'correct', 'The sun rises in the east.', null, 'only one sun'),
  ('bb7e5ea1-05fc-5242-a716-5d803a08c9d9', 'the-one-of-a-kind', 'correct', 'She is the best student in the class.', null, 'superlative'),
  ('eeeed710-4191-5658-bffc-75f9c1f301e3', 'the-one-of-a-kind', 'correct', 'It is the first day of the course.', null, 'ordinal number'),
  ('a92e7037-1cd2-596d-b402-f938937d1934', 'the-one-of-a-kind', 'incorrect', 'He is best player in the team.', 'He is the best player in the team.', 'superlative needs the'),
  ('b95313c3-a5f8-55a8-a316-12bbed273fba', 'the-one-of-a-kind', 'incorrect', 'She is the better writer than me.', 'She is a better writer than me.', 'a comparative (better) takes a, not the'),
  ('c5d7c508-246e-5f78-af33-b2e735bd1122', 'the-one-of-a-kind', 'exception', 'most people', null, 'most meaning "the majority" takes no article'),
  ('3ebdc522-aaca-51ba-90aa-7fac7883dcbd', 'no-article-in-general', 'correct', 'I love music.', null, 'music in general'),
  ('79ac28b4-9c7f-50e7-b3a5-0ecd5c9ec8eb', 'no-article-in-general', 'correct', 'Children need love and attention.', null, 'all children, in general'),
  ('5d158786-3793-5a9b-b35b-2cf8f1406c51', 'no-article-in-general', 'correct', 'The music at the party was too loud.', null, 'that particular music: the'),
  ('8811fe43-951c-52bf-b7cc-94cedf9f1281', 'no-article-in-general', 'incorrect', 'The life is not easy.', 'Life is not easy.', 'life in general: no article'),
  ('48ca1b67-7248-55cb-8af0-a64d9820310b', 'no-article-in-general', 'incorrect', 'I like the apples.', 'I like apples.', 'apples in general, not particular ones'),
  ('64ffba48-7560-5a87-8045-a40024727a59', 'no-article-in-general', 'exception', 'a cat / cats / the cat', null, 'I like cats (all), the cat (one we know), a cat (any one)'),
  ('e3613248-6bf6-5209-805f-646cf0f79d22', 'no-article-names-meals-languages', 'correct', 'I usually have breakfast at seven.', null, 'meal: no article'),
  ('bfb7bae1-0843-51b2-b14f-9a3118b312a7', 'no-article-names-meals-languages', 'correct', 'She speaks French and Spanish.', null, 'language: no article'),
  ('34d27558-3358-5d0e-8861-09da39705c50', 'no-article-names-meals-languages', 'correct', 'We had a wonderful lunch at the beach.', null, 'adjective + meal: a'),
  ('55e286ed-bb08-541d-aaf6-46992530f913', 'no-article-names-meals-languages', 'incorrect', 'I live in the Paris.', 'I live in Paris.', 'a city name: no article'),
  ('7f912e70-2d19-5f6c-a0b3-54e7e1e226fd', 'no-article-names-meals-languages', 'incorrect', 'He plays the chess very well.', 'He plays chess very well.', 'games and sports: no article'),
  ('3f081a79-7ca5-59a7-870f-86de3e26576a', 'no-article-names-meals-languages', 'exception', 'the Browns', null, 'the + plural surname means the whole family'),
  ('431b9927-0f19-53eb-8e38-d3476d729590', 'the-geography', 'correct', 'We crossed the Atlantic Ocean by ship.', null, 'ocean: the'),
