  ('343cb320-5c99-5832-b44b-f406551d5b8e', 'no-article-routine-places', 'incorrect', 'I go to the work at eight.', 'I go to work at eight.', 'work as a routine: no article'),
  ('893f033b-1d2a-5c08-b995-94563d3cc680', 'no-article-routine-places', 'incorrect', 'She stays in the bed when she is ill.', 'She stays in bed when she is ill.', 'in bed: no article'),
  ('799a3018-5854-59c1-a7ce-cb37e1decdad', 'no-article-routine-places', 'exception', 'I listen to the radio. We watched TV.', null, 'radio takes the, TV takes no article'),
  ('b405bd83-115b-5eb9-a938-149328ca78dc', 'a-with-jobs-and-quantities', 'correct', 'My mother is an engineer.', null, 'a job: a / an'),
  ('ee6dc32f-46dd-5a53-bd93-0fecadf85297', 'a-with-jobs-and-quantities', 'correct', 'She goes to the gym twice a week.', null, 'a = per'),
  ('8b23b7a7-59d5-5706-9934-47d8f2c17466', 'a-with-jobs-and-quantities', 'correct', 'What a beautiful day!', null, 'what a + singular noun'),
  ('58ecae54-9115-5584-8f04-f491132ebfd4', 'a-with-jobs-and-quantities', 'incorrect', 'He works as waiter.', 'He works as a waiter.', 'a job needs a / an'),
  ('e3c51247-7f92-526a-94e6-6c61fe109362', 'a-with-jobs-and-quantities', 'incorrect', 'It takes half hour.', 'It takes half an hour.', 'half an hour'),
  ('9e38c268-9141-5274-9958-c005405c925a', 'a-with-jobs-and-quantities', 'exception', 'Few people came. / A few people came.', null, 'few = almost none, a few = some')
) as v(id, slug, example_type, text, correction, note)
